sys_ux_client_script.script:
/**
  * @param {params} params
  * @param {api} params.api
  * @param {TransformApiHelpers} params.helpers
  */
function evaluateProperty({
    api,
    helpers
}) {

    var formFields = api.data.record.form ? api.data.record.form.fields : false;
    var formFieldsState = formFields ? formFields.state : false;
    var stateValue = formFieldsState ? formFieldsState.value : false;
    if (api.data.ribbonCtrl.secondaryItemsHeader)
        return false;
    else if (!api.data.wrap_up.enabledCodes && stateValue === 'wrap_up' && api.data.wrap_up.timeLeftInSecond > 0 && api.data.wrap_up.showTimer)
        return false;
    else
        return true;

}
